    def get_cookies(board):
        board = tuple(sorted(board))
        if board in memo:
            return memo[board]

        s = sum(board)
        for x in board:
            if x > s - x:
                return len(board)

        if all(x == 0 for x in board):
            return len(board)

        max_cookies = -1
        n = len(board)
        for i in range(n):
            for j in range(i + 1, n):
                x, y = board[i], board[j]

